import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
class PendingOrderCleanupJob {

    // Chay lai sau moi 5 phut TINH TU LUC LAN CHAY TRUOC KET THUC -
    // phu hop vi job nay khong can chay dung gio tuyet doi, chi can dinh ky.
    @Scheduled(fixedDelay = 5 * 60 * 1000)
    public void cancelStalePendingOrders() {
        Instant threshold = Instant.now().minus(30, ChronoUnit.MINUTES);
        List<Long> staleOrderIds = findPendingOrdersOlderThan(threshold);
        staleOrderIds.forEach(this::cancelOrder);
    }

    private List<Long> findPendingOrdersOlderThan(Instant threshold) { return List.of(); }
    private void cancelOrder(Long orderId) { }
}

import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import org.springframework.stereotype.Service;
import org.springframework.web.reactive.function.client.WebClient;

@Service
class PaymentGatewayClient {

    private final WebClient webClient;

    PaymentGatewayClient(WebClient.Builder builder) {
        this.webClient = builder.baseUrl("https://payments.example.com").build();
    }

    @CircuitBreaker(name = "paymentGateway", fallbackMethod = "paymentUnavailable")
    public PaymentResult charge(Long orderId, java.math.BigDecimal amount) {
        return webClient.post()
                .uri("/charge")
                .bodyValue(new ChargeRequest(orderId, amount))
                .retrieve()
                .bodyToMono(PaymentResult.class)
                .block();
    }

    // Fallback PHAI cung chu ky tra ve + them tham so Throwable o cuoi.
    private PaymentResult paymentUnavailable(Long orderId, java.math.BigDecimal amount, Throwable t) {
        return new PaymentResult(orderId, "PENDING_MANUAL_REVIEW");
    }

    record ChargeRequest(Long orderId, java.math.BigDecimal amount) {}
    record PaymentResult(Long orderId, String status) {}
}

